parameters.item/StatusMessage:
@if(
 equals(variables('AppResponseStatus'),'SUCCESS'),
 concat(
  'Emergency Report is available. TargetFile=',
  trim(string(outputs('CMP_ConfigObject')?['EmergencyReportFileName']))
 ),
 concat(
  'Emergency Report upload failed. Code=',
  variables('AppResponseCode')
 )
)

inputs.select:
@concat(
  ',',
  '"',
  replace(coalesce(item()?['Title'], ''), '"', concat(decodeUriComponent('%5C'), '"')),
  '":"',
  replace(
    replace(
      replace(
        replace(
          coalesce(
            if(
              equals(variables('OperationMode'), 'PROD_NODMP'),
              item()?['Value_PROD_NODMP'],
              if(
                equals(variables('OperationMode'), 'PROD_DMP'),
                item()?['Value_x002d_PROD_x0028_DMP_x0029'],
                if(
                  equals(variables('OperationMode'), 'SIMU_NODMP'),
                  coalesce(item()?['Value_x002d_SIMU_x0028_NODMP_x0029'], item()?['Value_x002d_SIMU_x0028_NODMP_x00']),
                  item()?['Value_x002d_SIMU_x0028_DMP_x0029']
                )
              )
            ),
            ''
          ),
          decodeUriComponent('%5C'),
          concat(decodeUriComponent('%5C'), decodeUriComponent('%5C'))
        ),
        '"',
        concat(decodeUriComponent('%5C'), '"')
      ),
      decodeUriComponent('%0D'),
      ''
    ),
    decodeUriComponent('%0A'),
    concat(decodeUriComponent('%5C'), 'n')
  ),
  '"'
)
